    #play{display:none;min-height:calc(100svh - 72px);padding:26px 0 50px}.game-head{display:flex;align-items:center;gap:12px;margin-bottom:16px}.title-block{min-width:0}.title-block h1{margin:0;overflow:hidden;font-size:clamp(23px,3.3vw,36px);letter-spacing:-.055em;text-overflow:ellipsis;white-space:nowrap}.title-block p{margin:3px 0 0;color:var(--muted);font-size:12px}.play-back{border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:transparent;color:var(--text);font:750 12px inherit;cursor:pointer}.play-back:hover{border-color:var(--green);color:var(--green)}.game-metrics{display:flex;gap:8px;margin-left:auto}.metric{min-width:83px;padding:8px 10px;border:1px solid var(--line);border-radius:10px;background:#151b15}.metric span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.07em}.metric b{display:block;margin-top:1px;font-size:16px}.metric b.green{color:var(--green)}.controls{display:flex;gap:6px}.control{display:grid;place-items:center;width:37px;height:37px;border:1px solid var(--line);border-radius:10px;background:#151b15;color:var(--text);font:700 12px inherit;cursor:pointer}.control:hover{border-color:var(--green);color:var(--green)}
